def b64(a): return base64.b64encode((np.clip(a,-1,1)*32767).astype('<i2').tobytes()).decode()

def ft2(name, args):
    r=subprocess.run(['ft2','call',name,json.dumps(args)],capture_output=True,text=True)
    if r.returncode!=0: raise RuntimeError(f'{name} failed: {r.stdout} {r.stderr}')
    return json.loads(r.stdout)['content'][0]['text']

def batch(calls):
    p='/tmp/_b.json'; json.dump(calls,open(p,'w'))
    r=subprocess.run(['ft2','batch',p],capture_output=True,text=True)
    if r.returncode!=0: raise RuntimeError(r.stdout[-1500:])

def render(path, loops=1, rate=44100):
    if os.path.exists(path): os.remove(path)
    ft2('module_render',{"path":path,"rate":rate,"bits":16,"loops":loops})
    w=wave.open(path)
    d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float).reshape(-1,w.getnchannels())
    return d, w.getframerate()

def zf(seg,sr=44100):
    s=seg-seg.mean(); z=np.where(np.diff(np.signbit(s)))[0]
    if len(z)<3: return 0.0
    return sr/(np.mean(np.diff(z))*2)

def save_sample(path, instr=1, sample=0):
    if os.path.exists(path): os.remove(path)
    ft2('sample_save',{"path":path,"instrument":instr,"sample":sample,"format":"wav"})
    w=wave.open(path)
    return np.frombuffer(w.readframes(w.getnframes()),dtype='<i2')
