    w=0.5*saw(32)+0.5*pulse(32,0.5)
    return lowpass_cycle(w, 0.5)

def lead_wave():
    return pulse(32,0.25)

def arp_wave():
    return pulse(32,0.125)

def pad_wave():
    return softsaw(32,7)

def sub_wave():
    return sine(32)

