    n=int(0.95*SR); t=np.arange(n)/SR
    noi=rng.standard_normal(n+1); noi=np.diff(noi); noi/=np.max(np.abs(noi))
    x=noi*np.exp(-t/0.26)
    x+=0.25*np.sin(2*np.pi*5200*t)*np.exp(-t/0.15)
